"use strict";

/**
 * Parity suite for @shexjs/extension-wasi <http://shex.io/extensions/WASI/>.
 *
 * test/wasi/ holds shexTest's SemanticAction validation tests re-coded for
 * the WASI extension (generated by tools/gen-tests.js): each Test semact is
 * replaced by a WAT/WASI command module printing the same line.  Every test
 * runs twice — the original schema under @shexjs/extension-test and the
 * re-coded schema under this extension — and must agree on validation
 * status and on the collected result lines; where the shexTest manifest
 * declares mf:extensionResults, both must match those too.
 */

const expect = require("chai").expect;
const Fs = require("fs");
const Path = require("path");
const N3 = require("n3");

const ShExParser = require("@shexjs/parser");
const {ShExValidator} = require("@shexjs/validator");
const {ctor: RdfJsDb} = require("@shexjs/neighborhood-rdfjs");
const ShExTerm = require("@shexjs/term");
const TestExtension = require("@shexjs/extension-test");
const WasiExtension = require("../shex-extension-wasi");

const TestUrl = "http://shex.io/extensions/Test/";
const WasiUrl = "http://shex.io/extensions/WASI/";
const ShexTestDir = Path.join(__dirname, "../../../../shexTest");
const WasiDir = Path.join(__dirname, "wasi");
const Manifest = JSON.parse(Fs.readFileSync(Path.join(WasiDir, "manifest.json"), "utf8"));

function parseTurtle (file, baseIRI) {
  const store = new N3.Store();
  new N3.Parser({baseIRI, blankNodePrefix: "", format: "text/turtle"})
    .parse(Fs.readFileSync(file, "utf8"))
    .forEach(q => store.addQuad(q));
  return store;
}

function parseSemActs (file, url) {
  return ShExParser.construct(url).parse(Fs.readFileSync(file, "utf8"))
    .startActs.reduce((ret, a) => { ret[a.name] = a.code; return ret; }, {});
}

/** run one validation, returning {status, results} */
function runOne (schemaFile, schemaURL, extension, semActsFile, entry) {
  const schema = ShExParser.construct(schemaURL, null, {index: true})
        .parse(Fs.readFileSync(schemaFile, "utf8"), schemaURL);
  const dataFile = Path.join(ShexTestDir, "validation", entry.data);
  const dataURL = "file://" + dataFile;
  const store = parseTurtle(dataFile, dataURL);
  const options = {};
  if (semActsFile)
    options.semActs = parseSemActs(semActsFile, "file://" + semActsFile);
  const validator = new ShExValidator(schema, RdfJsDb(store), options);
  const results = extension.register(validator, {ShExTerm});
  // The NoCode tests name their acts with fragments (…Test/#a) whose code
  // arrives via options.semActs; dispatchAll only routes names with a
  // registered handler, so alias the extension's handler under each.
  // (The stock Validation-test harness doesn't, which is why those tests'
  // extensionResults are never actually compared there.)
  Object.keys(options.semActs || {}).forEach(name => {
    if (name !== extension.url)
      validator.semActHandler.register(name, validator.semActHandler.handlers[extension.url]);
  });
  const map = [{node: new URL(entry.focus, dataURL).href,
                shape: new URL(entry.shape, schemaURL).href}];
  const outcome = validator.validateShapeMap(map);
  extension.done(validator);
  return {
    status: outcome.every(m => m.status === "conformant") ? "conformant" : "nonconformant",
    results: results.slice(),
  };
}

describe("@shexjs/extension-wasi", function () {
  this.timeout(20000);
  before(() => WasiExtension.ready());

  it("should look like a ShEx semantic-action extension", function () {
    expect(WasiExtension.url).to.equal(WasiUrl);
    expect(WasiExtension.name).to.equal("Wasi");
    expect(WasiExtension.register).to.be.a("function");
    expect(WasiExtension.done).to.be.a("function");
  });

  Manifest.forEach(entry => {
    describe(entry.name, function () {
      let reference, subject;
      before(function () {
        const origSchema = Path.join(ShexTestDir, entry.originalSchema);
        reference = runOne(origSchema, "file://" + origSchema, TestExtension,
                           entry.originalSemActs ? Path.join(ShexTestDir, entry.originalSemActs) : null,
                           entry);
        const wasiSchema = Path.join(WasiDir, entry.schema);
        subject = runOne(wasiSchema, "file://" + Path.join(ShexTestDir, "schemas", entry.schema), WasiExtension,
                         entry.semActs ? Path.join(WasiDir, entry.semActs) : null,
                         entry);
      });

      it("should agree with the Test extension on validation status", function () {
        expect(subject.status).to.equal(reference.status);
        expect(subject.status).to.equal(
          entry.status === "sht:ValidationFailure" ? "nonconformant" : "conformant");
      });

      it("should collect the same result lines as the Test extension", function () {
        expect(subject.results).to.deep.equal(reference.results);
      });

      if (entry.expectedPrints.length > 0)
        it("should print what the manifest's extensionResults declare", function () {
          expect(subject.results).to.deep.equal(entry.expectedPrints);
        });
    });
  });

  describe("node:wasi host parity", function () {
    it("should produce the same lines under Node's built-in WASI", function () {
      let hasWasi = true;
      try { require("node:wasi"); } catch (e) { hasWasi = false; }
      if (!hasWasi) this.skip();
      const entry = Manifest.find(e => e.name === "1dotCode1_pass");
      const wasiSchema = Path.join(WasiDir, entry.schema);
      const viaNodeWasi = runOne(wasiSchema, "file://" + Path.join(ShexTestDir, "schemas", entry.schema),
                                 WasiExtension.configure({impl: "wasi"}), null, entry);
      expect(viaNodeWasi.results).to.deep.equal(entry.expectedPrints);
    });
  });
});
